# -*- coding: utf-8 -*-
"""Seed ویکی تبار (tabar: lineage & genetics) on the shared core.
Writes data/tabar/concepts/*.json, iran/*.json, and adds people/sources to core/*.json (additive, never removes).
Content is editorial draft (status: draft) until Maryam/experts review. Sources are tier 1 (journal) or 2 (book)."""
import json, os, hashlib, re
HERE = os.path.dirname(os.path.abspath(__file__)); R = os.path.abspath(HERE + '/..')
def load(p, d): return json.load(open(p, encoding='utf-8')) if os.path.exists(p) else d
people = load(f'{R}/core/people.json', {}); sources = load(f'{R}/core/sources.json', {})

def src(cite, tier=1, url=None):
    year = re.search(r'\((\d{4})\)', cite); year = int(year.group(1)) if year else None
    for k, v in sources.items():
        if v['cite'] == cite:
            if 'tabar' not in v['wikis']: v['wikis'].append('tabar')
            return k
    sid = 'src:' + hashlib.md5(cite.encode()).hexdigest()[:10]
    sources[sid] = {'id': sid, 'cite': cite, 'year': year, 'tier': tier, 'wikis': ['tabar']}
    if url: sources[sid]['url'] = url
    return sid

def person(latin, fa, years='', note=''):
    pid = 'core:' + re.sub(r'[^a-z0-9]+', '-', latin.lower()).strip('-')
    if pid not in people:
        people[pid] = {'id': pid, 'name': {'fa': fa, 'en': latin, 'nl': latin}, 'years': years, 'note': {'fa': note}, 'wikidata': None, 'wikis': []}
    if 'tabar' not in people[pid]['wikis']: people[pid]['wikis'].append('tabar')
    return pid

