# ---------------- concepts ----------------
C = []
def t(fa, en, nl=None): return {'fa': fa, 'en': en, 'nl': nl or en}
def pt(fa, en, srcs, flags=()): return {'text': t(fa, en), 'sources': [S[s] if s in S else s for s in srcs], 'flags': list(flags)}
def ln(to, rel, fa, en): return {'to': to, 'rel': rel, 'note': t(fa, en)}
def add(id, kind, title, summary, parent=None, field=None, points=(), links=(), ppl=(), iran=None, origin=None, aliases=(), wikidata=None):
    srcs = sorted({s for p in points for s in p['sources']})
    C.append({'id': 'tabar:' + id, 'kind': kind, 'title': title, 'aliases': list(aliases), 'parent': parent and 'tabar:' + parent, 'field': field and 'tabar:' + field,
              'summary': summary, 'points': list(points), 'links': list(links), 'people': [P[p] for p in ppl], 'sources': srcs, 'booklets': [],
              'origin': origin, 'iran': iran, 'wikidata': wikidata, 'status': 'draft'})

